package fcm

import (
	"encoding/json"
	"fmt"
	"log/slog"
	"strings"
	"time"

	"github.com/arandu-io/hesape/database/model"
)

// Device is one phone that can receive a push: the registration token Firebase
// gave an installation of the application, whose user it belongs to, and which
// platform it runs on. The token is sealed at rest and never leaves in a
// response, a log line or a JSON encoding.
//
// Devices, DeviceQuery and DeviceCollection are generated beside this file, in
// DeviceQuery.go, by aru model:build.
type Device struct {
	model.Model

	// ID is the identifier, generated by the application.
	ID string `db:"id"`

	// TenantID is the tenant the device belongs to. It is written from the
	// Grant and read back so the policy can compare it against the subject's
	// tenant.
	TenantID string `db:"tenant_id"`

	// UserID is the subject the device belongs to, the one who registered it.
	UserID string `db:"user_id"`

	// Token is the sealed registration token. Read it with the module's sealer
	// only; the clear value is never stored.
	Token string `db:"token"`

	// TokenHash is the keyed digest of the registration token inside the
	// tenant: what makes registering the same token twice find the same row
	// without the clear token being stored.
	TokenHash string `db:"token_hash"`

	// Platform is the operating system of the phone: android or ios.
	Platform Platform `db:"platform"`

	// App is the application id (the Android package or the iOS bundle) the
	// token was issued to.
	App string `db:"app"`

	// Locale is the language of the installation, a BCP 47 tag such as pt-BR,
	// empty when the application did not say.
	Locale string `db:"locale"`

	// LastSeenAt is when the installation last registered itself.
	LastSeenAt time.Time `db:"last_seen_at"`

	CreatedAt time.Time `db:"created_at"`
	UpdatedAt time.Time `db:"updated_at"`
}

// deviceTable is the table Device is a row of, declared once. Its query,
// Devices, is generated beside it and is the one way to reach the rows.
//
// ManualKey because the primary key is text the application writes. The tenant
// scope is left at its tenant_id default.
var deviceTable = model.NewTable(model.TableSpec{
	Name:      devicesTable,
	New:       func() model.Entity { return new(Device) },
	ManualKey: true,
})

// devicesTable is the name of the table the module owns.
const devicesTable = "fcm_devices"

// Platform is the operating system of a phone.
type Platform string

// The platforms Firebase pushes to through this module.
const (
	// PlatformAndroid is an Android phone; its message carries the android
	// block.
	PlatformAndroid Platform = "android"
	// PlatformIOS is an iPhone; its message carries the apns block, and the
	// APNs key uploaded to Firebase delivers it.
	PlatformIOS Platform = "ios"
)

// ParsePlatform reads a platform the way an application spells it, in any case,
// and reports whether it is one this module sends to.
func ParsePlatform(value string) (Platform, bool) {
	switch p := Platform(strings.ToLower(strings.TrimSpace(value))); p {
	case PlatformAndroid, PlatformIOS:
		return p, true
	}
	return "", false
}

// arandu:begin custom

// Reassign gives the device to another user and refreshes what the
// installation says about itself. It is the one rule of registering a token
// that is already known: the same token replaces its earlier registration
// instead of adding a second row.
func (d *Device) Reassign(userID string, platform Platform, app, locale string, now time.Time) {
	d.UserID = userID
	d.Platform = platform
	d.App = app
	d.Locale = locale
	d.LastSeenAt = now
	d.UpdatedAt = now
}

// MarshalJSON encodes the device as its resource, so an encoder handed the
// entity answers with the fields a response may carry and never the sealed
// token or its digest.
func (d *Device) MarshalJSON() ([]byte, error) {
	if d == nil {
		return []byte("null"), nil
	}
	return json.Marshal(NewDeviceResource(d).ToArray())
}

// LogValue is what a logger records of the device: who it belongs to and what
// it runs on, never a token, sealed or not.
func (d *Device) LogValue() slog.Value {
	if d == nil {
		return slog.StringValue("")
	}
	return slog.GroupValue(
		slog.String("id", d.ID),
		slog.String("tenant", d.TenantID),
		slog.String("user", d.UserID),
		slog.String("platform", string(d.Platform)),
		slog.String("app", d.App),
	)
}

// String is the device without its token.
func (d *Device) String() string {
	if d == nil {
		return "fcm.Device(nil)"
	}
	return fmt.Sprintf("fcm.Device{id:%s user:%s platform:%s app:%s}", d.ID, d.UserID, d.Platform, d.App)
}

// arandu:end custom

// ErrNotFound is returned when no row matches, including when the row exists
// in another tenant or belongs to another user. The cases are deliberately
// indistinguishable.
//
// It wraps model.ErrModelNotFound, so the router answers it with 404 and a
// caller can still ask for it by name with errors.Is.
var ErrNotFound = fmt.Errorf("fcm: device not found: %w", model.ErrModelNotFound)

// DeviceResource is the list of fields one Device is allowed to answer with.
//
// A declared list rather than the entity itself: the sealed token, its digest
// and the tenant are exactly the fields that belong in no response.
type DeviceResource struct {
	id         string
	userID     string
	platform   Platform
	app        string
	locale     string
	lastSeenAt time.Time
	createdAt  time.Time
}

// NewDeviceResource snapshots one device for the response.
func NewDeviceResource(d *Device) DeviceResource {
	if d == nil {
		return DeviceResource{}
	}
	return DeviceResource{
		id: d.ID, userID: d.UserID, platform: d.Platform, app: d.App, locale: d.Locale,
		lastSeenAt: d.LastSeenAt, createdAt: d.CreatedAt,
	}
}

// ToArray returns the fields that may leave, by name.
func (r DeviceResource) ToArray() map[string]any {
	return map[string]any{
		"id":           r.id,
		"user_id":      r.userID,
		"platform":     string(r.platform),
		"app":          r.app,
		"locale":       r.locale,
		"last_seen_at": r.lastSeenAt.UTC().Format(time.RFC3339),
		"created_at":   r.createdAt.UTC().Format(time.RFC3339),
	}
}

// With returns what goes beside the fields at the top level of the response.
// Nothing does here.
func (r DeviceResource) With() map[string]any { return nil }

// DevicesResource is a list of devices as one response.
type DevicesResource struct {
	items []DeviceResource
}

// NewDevicesResource wraps devices for the response.
func NewDevicesResource(devices []*Device) DevicesResource {
	items := make([]DeviceResource, 0, len(devices))
	for _, d := range devices {
		if d != nil {
			items = append(items, NewDeviceResource(d))
		}
	}
	return DevicesResource{items: items}
}

// ToArray returns the list under a single key, so that the shape of the
// response does not change when a second key is added beside it.
func (c DevicesResource) ToArray() map[string]any {
	items := make([]map[string]any, 0, len(c.items))
	for _, item := range c.items {
		items = append(items, item.ToArray())
	}
	return map[string]any{"items": items}
}

// With returns nothing: a list of one user's devices has no next page.
func (c DevicesResource) With() map[string]any { return nil }
